/**
 * @file src/lib/martAutoPurchaseSnapshot.ts
 * Snapshot for MartAutoPurchaseModal.
 */

import { POKEMART_ITEMS, POKEMART_AUTO_PURCHASE } from '../../constants/balance/pokemartDust.js';
import type { GameRuntime } from '../types/game.js';
import { publishDeferred } from '../bus/pub.js';
import { GameEventType as Evt } from '../bus/events.js';
import { formatNumber } from '../../formatters.ts';
import { getAllItem } from '../ui/uiItems.ts';
import { uiDataText } from '../ui/i18n.ts';
import { getItemIconHTML } from '../ui/utils.ts';

const POKEDOLLARS_IMG = '<img src="img/pokedollars.png" class="pokedollars-inline" alt="">';
const DUST_IMG = '<img src="img/essence-dust.png" class="essence-dust-inline" alt="">';

export type MartAutoPurchaseGroupId = 'balls' | 'stones' | 'mulch' | 'trade' | 'dust';

export interface MartAutoPurchaseItemSnapshot {
  key: string;
  displayName: string;
  description: string;
  costHtml: string;
  iconHtml: string;
  selected: boolean;
}

export interface MartAutoPurchaseGroupSnapshot {
  id: MartAutoPurchaseGroupId;
  title: string;
  items: MartAutoPurchaseItemSnapshot[];
}

export interface MartAutoPurchaseSnapshot {
  title: string;
  penaltyHintHtml: string;
  closeLabel: string;
  groups: MartAutoPurchaseGroupSnapshot[];
  selectedCount: number;
}

type PokeMartEntry = {
  name?: string;
  description?: string;
  itemId?: string;
  icon?: string;
  img?: string;
  cost?: number;
  dustCost?: number;
  costItems?: Array<{ itemId: string; qty: number }>;
};

function uiT(game: GameRuntime, key: string, fallback: string, params?: Record<string, string | number>): string {
  if (typeof game.t === 'function') {
    const translated = game.t(key, params);
    if (translated && translated !== key) return translated;
  }
  if (!params) return fallback;
  return Object.entries(params).reduce(
    (acc, [k, v]) => acc.replace(new RegExp(`\\{${k}\\}`, 'g'), String(v)),
    fallback,
  );
}

function getGroupId(key: string, entry: PokeMartEntry): MartAutoPurchaseGroupId {
  if (Number(entry.dustCost) > 0) return 'dust';
  if (key === 'growth_mulch_shop' || key === 'damp_mulch_shop') return 'mulch';
  if (key.includes('ball')) return 'balls';
  if (key.includes('stone')) return 'stones';
  return 'trade';
}

function buildBarterCostHtml(entry: PokeMartEntry): string {
  return (entry.costItems || [])
    .map((c) => {
      const def = getAllItem(c.itemId) ?? null;
      const icon = getItemIconHTML(def || { itemId: c.itemId });
      return `<span class="mart-auto-purchase-barter-line">${c.qty}×${icon}</span>`;
    })
    .join('<span class="mart-auto-purchase-cost-sep"> + </span>');
}

function buildCostHtml(game: GameRuntime, entry: PokeMartEntry): string {
  const hasBarter = Array.isArray(entry.costItems) && entry.costItems.length > 0;
  if (hasBarter) {
    return buildBarterCostHtml(entry);
  }
  if (Number(entry.dustCost) > 0) {
    const dustCost = formatNumber(Number(entry.dustCost) || 0);
    const dustWord = uiT(game, 'shop.martAutoPurchaseCostDustWord', 'Dust');
    return `${DUST_IMG} ${dustCost} ${dustWord}`;
  }
  const base = Number(entry.cost) || 0;
  const taxed = Math.ceil(base * (1 + POKEMART_AUTO_PURCHASE.pokedollarTaxRate));
  const autoLabel = uiT(game, 'shop.martAutoPurchaseCostAutoSuffix', 'auto');
  return `${POKEDOLLARS_IMG} ${formatNumber(base)} <span class="mart-auto-purchase-tax">(+30% ${autoLabel}: ${formatNumber(taxed)})</span>`;
}

function buildPenaltyHintHtml(game: GameRuntime, taxPct: number, rjFee: number): string {
  return uiT(
    game,
    'shop.martAutoPurchasePenaltyHint',
    `+{tax}% sur les achats en Pokédollars et {rj} Jetons Rocket par transaction.`,
    { tax: taxPct, rj: formatNumber(rjFee) },
  );
}

export function buildMartAutoPurchaseSnapshot(game: GameRuntime): MartAutoPurchaseSnapshot {
  const selected = new Set(
    Array.isArray(game.martState?.autoPurchaseKeys) ? game.martState!.autoPurchaseKeys : [],
  );
  const rjFee = typeof game.getPokeMartAutoPurchaseRjFee === 'function'
    ? game.getPokeMartAutoPurchaseRjFee()
    : POKEMART_AUTO_PURCHASE.baseRjFee;
  const taxPct = Math.round(POKEMART_AUTO_PURCHASE.pokedollarTaxRate * 100);

  const groupTitles: Record<MartAutoPurchaseGroupId, string> = {
    balls: uiT(game, 'shop.martAutoPurchaseGroupBalls', 'Poké Balls'),
    stones: uiT(game, 'shop.martAutoPurchaseGroupStones', 'Evolution stones'),
    mulch: uiT(game, 'shop.martAutoPurchaseGroupMulch', 'Mulch'),
    trade: uiT(game, 'shop.martAutoPurchaseGroupTrade', 'Trade & misc'),
    dust: uiT(game, 'shop.martAutoPurchaseGroupDust', 'Essence Dust'),
  };

  const buckets: Record<MartAutoPurchaseGroupId, MartAutoPurchaseItemSnapshot[]> = {
    balls: [],
    stones: [],
    mulch: [],
    trade: [],
    dust: [],
  };

  const source = POKEMART_ITEMS as Record<string, PokeMartEntry>;
  for (const [key, entry] of Object.entries(source)) {
    if (!entry) continue;
    const groupId = getGroupId(key, entry);
    const realItem = entry.itemId ? getAllItem(entry.itemId) ?? null : null;
    const iconHtml = getItemIconHTML(realItem || entry);
    buckets[groupId].push({
      key,
      displayName: uiDataText(game, 'pokeMart', key, 'name', entry.name || key),
      description: entry.description || '',
      costHtml: buildCostHtml(game, entry),
      iconHtml,
      selected: selected.has(key),
    });
  }

  const groupOrder: MartAutoPurchaseGroupId[] = ['balls', 'stones', 'mulch', 'trade', 'dust'];
  const groups = groupOrder
    .map((id) => ({
      id,
      title: groupTitles[id],
      items: buckets[id].sort((a, b) => a.displayName.localeCompare(b.displayName)),
    }))
    .filter((g) => g.items.length > 0);

  return {
    title: uiT(game, 'shop.martAutoPurchaseTitle', 'Auto-Purchase'),
    penaltyHintHtml: buildPenaltyHintHtml(game, taxPct, rjFee),
    closeLabel: uiT(game, 'shop.martAutoPurchaseClose', 'Close'),
    groups,
    selectedCount: selected.size,
  };
}

export function buildMartAutoPurchaseButtonLabel(game: GameRuntime): string {
  const count = Array.isArray(game.martState?.autoPurchaseKeys)
    ? game.martState!.autoPurchaseKeys.length
    : 0;
  const base = uiT(game, 'shop.martAutoPurchaseButton', 'Auto-Purchase');
  return count > 0 ? `${base} (${count})` : base;
}

export function isMartAutoPurchaseModalVisible(): boolean {
  if (typeof document === 'undefined') return false;
  return document.getElementById('martAutoPurchaseModal')?.classList.contains('show') ?? false;
}

export function publishMartAutoPurchaseChanged(opts?: { force?: boolean }): void {
  if (!opts?.force && !isMartAutoPurchaseModalVisible()) return;
  publishDeferred(Evt.MART_AUTO_PURCHASE_UPDATED, () => ({
    type: Evt.MART_AUTO_PURCHASE_UPDATED,
  }));
}
